import * as s from "../core/validation/index.js";
import type { Schema } from "../core/validation/schema.js";
import { completeresponseSchema, type Completeresponse } from "./unions/completeresponse.js";
import { securepayloadSchema, type Securepayload } from "./unions/securepayload.js";

export type PazeSessionComplete = {
  /**
   * Unique identifier generated by Paze to track and link the wallet transaction. Used as the
   * wallet transaction identifier.
   */
  payloadId: string;
  /** Opaque token returned by Paze for the completion call. */
  completeResponse: Completeresponse;
  /**
   * Signed and encrypted payload containing the data necessary to process the payment. Returned
   * when `payloadTypeIndicator` is PAYMENT.
   */
  securePayload: Securepayload;
  /** Echo of the `clientContext` sent on the request. Returned by Paze for client-side tracing. */
  clientContext: string;
  /** Paze-issued session identifier returned for tracing. */
  ewSid: string;
  /** Server timestamp of the Paze response in ISO 8601 format. Returned for tracing. */
  timestampIso8601: string;
};

export const pazeSessionCompleteSchema: Schema<PazeSessionComplete> = s.object<PazeSessionComplete>({
  payloadId: s.string(),
  completeResponse: completeresponseSchema,
  securePayload: securepayloadSchema,
  clientContext: s.string(),
  ewSid: s.string(),
  timestampIso8601: s.string(),
  _keysMap: {
    ewSid: "ewSID",
    timestampIso8601: "timestampISO8601",
  },
});
